<script setup lang="ts">import {ref,computed} from 'vue';import type {Snapshot,Run,User} from '../types/domain';import {researchApi} from '../api/research';import {useAsync} from '../hooks/useAsync';import PageTitle from '../components/common/PageTitle.vue';import RunTable from '../components/RunTable.vue';import Notice from '../components/common/Notice.vue';const props=defineProps<{snapshots:Snapshot[];runs:Run[];features:Record<string,string>;user:User;reload:()=>Promise<any>}>();const emit=defineEmits<{select:[run:Run]}>();const name=ref('十一月采集分布复校'),referenceId=ref(0),candidateId=ref(0),selected=ref<string[]>([]),bins=ref(6),smoothing=ref(.5),alpha=ref(.05),language=ref(''),device=ref('');const refs=computed(()=>props.snapshots.filter(s=>s.kind==='reference')),cands=computed(()=>props.snapshots.filter(s=>s.kind==='candidate')),chosen=computed(()=>selected.value.length?selected.value:Object.keys(props.features));const {task,act}=useAsync();function toggle(key:string){const next=chosen.value.includes(key)?chosen.value.filter(k=>k!==key):[...chosen.value,key];if(next.length)selected.value=next}async function submit(){await act(async()=>{const run=await researchApi.queue({name:name.value,reference_id:referenceId.value||refs.value[0]?.id,candidate_id:candidateId.value||cands.value[0]?.id,features:chosen.value,bins:bins.value,smoothing:smoothing.value,fdr_alpha:alpha.value,slice_language:language.value||null,slice_device:device.value||null});await props.reload();emit('select',run)},'比较已进入队列')};</script><template><PageTitle index="03 / COMPARISON PROTOCOL" title="先定箱，再比较。" description="分位边界只看参考快照，平滑伪计数同时加到各个桶。连续检验作为一个检验族执行BH校正。"/><div class="compare-layout"><form class="editor" @submit.prevent="submit"><h2>建立一份可复算的比较</h2><fieldset :disabled="task.busy||user.role==='viewer'"><label>校样名称<input v-model="name" required maxlength="100"/></label><div class="form-grid"><label>参考快照<select v-model="referenceId"><option :value="0" v-if="refs.length">{{refs[0].name}}</option><option v-for="s in refs" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>候选快照<select v-model="candidateId"><option :value="0" v-if="cands.length">{{cands[0].name}}</option><option v-for="s in cands" :key="s.id" :value="s.id">{{s.name}}</option></select></label></div><label>比较特征</label><div class="feature-checks"><label v-for="(label,key) in features" :key="key"><input type="checkbox" :checked="chosen.includes(String(key))" @change="toggle(String(key))"/>{{label}}</label></div><div class="form-grid"><label>参考分位箱数<input type="number" v-model.number="bins" min="2" max="10" step="1"/></label><label>每桶平滑伪计数<input type="number" v-model.number="smoothing" min=".1" max="10" step=".1"/></label><label>BH FDR α<input type="number" v-model.number="alpha" min=".01" max=".2" step=".01"/></label><label>语言切片 / 留空为全量<input v-model="language" placeholder="例如 zh" maxlength="40"/></label><label>设备切片 / 留空为全量<input v-model="device" placeholder="例如 mobile" maxlength="40"/></label></div><button class="primary" :disabled="!refs.length||!cands.length">{{task.busy?'正在提交…':'冻结参考箱并比较 →'}}</button></fieldset><p v-if="user.role==='viewer'">观察员可阅读校样；提交需要研究员权限。</p><Notice :error="task.error" :message="task.message"/></form><aside class="method-column"><small>METHOD NOTES / 排版规则</small><h2>差异有多大，<br/>证据有多强。</h2><ol><li><b>PSI · 自然对数</b><p>Σ(q−p)ln(q/p)，平滑后不出现零分母；阈值.2仅是人工核对启发。</p></li><li><b>JS · log₂</b><p>两边与共同中点的平均KL，值在0到1；同一冻结箱内交换两分布保持对称。</p></li><li><b>KS + BH</b><p>连续特征双侧KS只看非缺失值。所选连续特征原p统一做BH，按q≤α报告FDR拒绝。</p></li></ol><p class="fine">样本差异不证明模型劣化。先核对采集来源、分层和缺失原因，再讨论补采。</p></aside></div><div class="section-title"><h2>比较队列与校样</h2><small>后端每3秒更新状态</small></div><RunTable :runs="runs" @select="emit('select',$event)"/></template>
